import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25, C: 33.33, D: 100, E: 0.5 }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = async (items) => {
  const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })
  return { status: res.status, body: await res.json() }
}

test('total is sum of price * qty without discount at or below 100', async () => {
  assert.equal((await post([{ sku: 'A', qty: 3 }, { sku: 'B', qty: 2 }])).body.total, 80)
})

test('exactly 100 gets no discount (threshold is exclusive)', async () => {
  assert.equal((await post([{ sku: 'D', qty: 1 }])).body.total, 100)
})

test('orders over 100 get 10% off', async () => {
  assert.equal((await post([{ sku: 'A', qty: 11 }])).body.total, 99) // 110 -> 99
  assert.equal((await post([{ sku: 'D', qty: 2 }])).body.total, 180)
})

test('just over threshold is discounted', async () => {
  // 100.5 -> 90.45 -> floored to 90
  assert.equal((await post([{ sku: 'D', qty: 1 }, { sku: 'E', qty: 1 }])).body.total, 90)
})

test('discount is flat 10% for very large orders (no tiers)', async () => {
  assert.equal((await post([{ sku: 'D', qty: 100 }])).body.total, 9000)
})

test('total is floored to whole euros (cents are dropped)', async () => {
  assert.equal((await post([{ sku: 'C', qty: 1 }])).body.total, 33)
  assert.equal((await post([{ sku: 'C', qty: 4 }])).body.total, 133 * 0.9 | 0) // 133.32*0.9=119.988 -> 119
})

test('created order is retrievable with same total', async () => {
  const { body } = await post([{ sku: 'D', qty: 2 }])
  const got = await (await fetch(`${base}/orders/${body.id}`)).json()
  assert.deepEqual(got, body)
})

test('validation', async () => {
  assert.equal((await post([])).status, 400)
})
EOF
